const b = $json.body || {};
// Modo prueba: el probador manda "prueba" (un id de conversación). No toca Kommo, no guarda pedidos ni escalamientos.
const prueba = String(b.prueba || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 60);
const leadId = prueba ? '' : String(b.leadId || '').trim();
return [{ json: {
  leadId,
  prueba: !!prueba,
  sessionId: prueba ? 'prueba_' + prueba : (leadId ? 'lead_' + leadId : 'sin_lead_' + Date.now()),
  mensaje: String(b.chatInput || '').trim(),
  directo: b.directo === true,
  marca: String(b.marca || '').toLowerCase(),
  nombre: String(b.nombre || '').trim(),
  telefono: String(b.telefono || '').replace(/\D/g, ''),
  archivo: (() => { const a = String(b.file || '').trim(); return a && a !== 'null' && a !== String(b.chatInput || '').trim() ? a : ''; })(),
} }];

const n0 = $('Normalizar').first().json;
// v4.12: cuando el cliente manda foto/audio/archivo, ByteGPT reenvía TODO lo que el cliente ya había escrito, pegado en un solo mensaje.
// Aquí se quita lo que el bot ya contestó en turnos anteriores, y el error de Kommo «Unable to open this message…» se cambia por un aviso de archivo.
const MARCA = '(foto, audio o archivo)';
const errKommo = t => String(t || '').replace(/Unable to open this message\.?[\s\S]*?(https?:\/\/\S*kommo\S*|$)/gi, ' ' + MARCA + ' ');
const previas = (Array.isArray($json.entradas_previas) ? $json.entradas_previas : []).join('\n');
const trozos = [...new Set(previas.split('\n').map(s => s.trim()).filter(s => s.length >= 4 && !s.startsWith('[SISTEMA') && !s.startsWith('Te envié un archivo')))].sort((a, b) => b.length - a.length);
const mBase = errKommo($json.mensajes).trim();
const quitar = (t, lista) => { let x = String(t || ''); for (const s of lista) if (s && x.includes(s)) x = x.split(s).join(' '); return x; };
let msg = errKommo(n0.mensaje);
const traeArchivo = msg.includes(MARCA) || mBase.includes(MARCA);
msg = quitar(msg.split(MARCA).join(' '), trozos);
msg = quitar(msg, mBase.split('\n').map(s => s.trim()).filter(s => s.length >= 4).sort((a, b) => b.length - a.length));
msg = msg.replace(/\s+/g, ' ').trim();
const n = { ...n0, mensaje: msg };
const m = mBase.split('\n').filter(l => !l.includes(MARCA) || l.split(MARCA).join('').trim()).map(l => l.split(MARCA).join('').trim()).filter(Boolean).join('\n');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
const ultima = String($json.ultima_respuesta || '');
// Candado anti-eco: si ByteGPT manda la respuesta anterior del bot en vez del mensaje del cliente, se ignora
const cm = norm(n.mensaje), cu = norm(ultima);
const ult = [ultima, ...(Array.isArray($json.ultimas) ? $json.ultimas : [])].map(norm).filter(x => x.length > 15);
const esEco = t => { const x = norm(t); return x.length > 15 && ult.some(u => u === x || u.includes(x) || x.includes(u)); };
const eco = (cm.length > 0 && cu.length > 0 && (cm === cu || (cm.length > 25 && (cu.includes(cm) || cm.includes(cu))))) || esEco(n.mensaje);
// Quita los renglones que en realidad son respuestas del bot que regresaron como si fueran del cliente
const mLimpio = m.split('\n').filter(l => !esEco(l)).join('\n').trim();
let entrada = mLimpio;
if (!eco && n.mensaje && !mLimpio.toLowerCase().includes(n.mensaje.toLowerCase())) entrada = (mLimpio ? mLimpio + '\n' : '') + n.mensaje;
// Ubicación: liga de Google Maps / Waze / Apple, o coordenadas sueltas
let ubicacion = '';
const arch = String(n.archivo || '');
const todo = entrada + ' ' + arch;
const liga = todo.match(/https?:\/\/[^\s]*(maps|goo\.gl|waze|maps\.apple)[^\s]*/i);
if (liga) ubicacion = liga[0];
else {
  const co = todo.match(/(-?\d{1,2}\.\d{4,})\s*,\s*(-?\d{2,3}\.\d{4,})/);
  if (co) ubicacion = `https://www.google.com/maps/search/?api=1&query=${co[1]},${co[2]}`;
}
// Si solo llegó un archivo/ubicación (sin texto), se arma un mensaje para que el bot conteste
if (!entrada.trim() && ubicacion) entrada = 'Te comparto mi ubicación: ' + ubicacion;
else if (!entrada.trim() && arch && /\.webp(\?|$)|sticker|figurinha/i.test(arch)) entrada = '[SISTEMA: el cliente mandó un sticker, sin texto]';
else if (!entrada.trim() && arch) entrada = 'Te envié un archivo: ' + arch;
// Sticker: ByteGPT manda el aviso en portugués («figurinha») o la liga .webp; se le dice a la IA que fue un sticker (no un archivo que no ve)
if (!eco && /figurinha|sticker/i.test(entrada) && entrada.length < 300) entrada = '[SISTEMA: el cliente mandó un sticker o emoji, sin texto]';
// v4.10: si llegó un mensaje SIN texto y no es eco (casi siempre es el pin de ubicación de WhatsApp, que ByteGPT manda vacío),
// el bot NO se queda callado: lo toma como ubicación y sigue con lo que faltaba del pedido.
// Antes se contestaba vacío y el salesbot de Kommo se detenía: el cliente seguía escribiendo y nadie le contestaba.
let sinTexto = false;
if (!eco && !entrada.trim()) { sinTexto = true; entrada = '[SISTEMA: el cliente mandó su ubicación; se anexará a su pedido cuando se registre. (Llegó un mensaje sin texto: casi siempre es el pin de ubicación de WhatsApp.) Agradécela en pocas palabras y sigue con la pregunta que tenías pendiente.]'; }
if (traeArchivo && !eco) {
  const aviso = '[SISTEMA: el cliente mandó una foto, audio o archivo que no puedes ver. No repitas lo que ya contestaste. Si con su texto ya sabes qué necesita, sigue; si no, pídele en una frase que te lo escriba.]';
  if (sinTexto || !entrada.trim()) { entrada = aviso; sinTexto = false; } else if (!entrada.includes('[SISTEMA: el cliente mandó una foto')) entrada = entrada.trim() + '\n' + aviso;
}
return [{ json: { ...n, entrada: entrada.trim(), eco, corte: $json.corte, ubicacion, sin_texto: sinTexto } }];

