const a = $input.first().json;
const n = $('Armar entrada').first().json;
const ctx = (() => { try { return $('Contexto').first().json || {}; } catch (e) { return {}; } })();
let respuesta = String(a.output || '').trim();
const pasos = (a.intermediateSteps || []).filter(s => s && s.action && s.action.tool);
const usadas = pasos.map(s => s.action.tool);
const registrado = usadas.includes('pasar_a_humano') || usadas.includes('consolidar_pedido');
// Solo cuenta si el bot PROMETE seguimiento humano (no cuando le pide al cliente que confirme algo)
const promete = /(un|el|nuestro)\s+asesor[^.?!]{0,40}(te\s+)?(contact|confirm|comunic|revis|atiend|llam|busc|apoy)|permíteme confirmarlo|en breve te contact|te comunico con|hablar con (un|una) (asesor|persona)/i.test(respuesta);
const falsaAlarma = /(tono|tonos|colores?)\b/i.test(respuesta) || /fecha (de entrega|exacta)|pedido (ya )?(qued[oó] )?registrado|folio/i.test(respuesta);
const mat = a.materiales === true;   // v4.17: lead de materiales (Lomas Ajusco): se pasa a una persona para darle el precio
let auto = (promete && !registrado && !falsaAlarma) || mat;
let falloIa = false;
if (!respuesta) {
  // La IA falló (sin saldo, límite, etc.): en vez de solo "te atiende un asesor", se da la lista de precios real
  falloIa = true; auto = true;
  // v4.19: ya no se manda la lista completa (16 productos). Si es el primer mensaje, solo el Slim (el del anuncio) y se pide el CP;
  // si la plática ya iba avanzada, no se reinicia la venta: se avisa corto y la tarea queda para una persona.
  let previos = 0; try { previos = Number($('¿Ya le contestó el bot?').first().json.previos || 0); } catch (e) {}
  const slim = String(ctx.lista || '').split('\n').filter(l => /slim|bala/i.test(l)).join('\n').trim();
  respuesta = previos > 0
    ? 'Recibí tu mensaje. Dame un momento y te respondo por aquí.'
    : slim
      ? 'Gracias por escribirnos. Estos son los precios del tinaco Slim (el del anuncio), con envío gratis en CDMX y Edomex:\n' + slim + '\nTambién hay tinacos clásicos desde 450 L. ¿Me pasas tu código postal y te digo qué día te llega?'
      : 'Gracias por escribirnos. Dame un momento y te respondo por aquí.';
}
const paso = pasos.find(s => s.action.tool === 'pasar_a_humano');
const ti = paso ? (typeof paso.action.toolInput === 'object' ? paso.action.toolInput : {}) : {};
const cambioPed = pasos.some(s => s.action.tool === 'consolidar_pedido' && /YA REGISTRADO/.test(typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || '')));
const escalo = usadas.includes('pasar_a_humano') || auto || cambioPed;
const motivo = mat ? 'cliente de materiales (Lomas Ajusco): darle precio' : (ti.motivo || (cambioPed ? 'cambio de pedido' : falloIa ? 'la IA no pudo contestar' : auto ? 'el bot prometió seguimiento' : 'otro'));
// Detalle de herramientas para el análisis semanal: qué se le preguntó y qué contestó cada una
const corta = (v, k) => { const t = typeof v === 'string' ? v : JSON.stringify(v ?? ''); return t.length > k ? t.slice(0, k) + '…' : t; };
const detalle = pasos.length ? JSON.stringify(pasos.map(s => {
  const inp = typeof s.action.toolInput === 'object' ? Object.fromEntries(Object.entries(s.action.toolInput || {}).filter(([k]) => k !== 'tool' && k !== 'id')) : s.action.toolInput;
  return { h: s.action.tool, in: corta(inp, 250), out: corta(s.observation, 300) };
})) : '';
// Etapa del embudo en este turno
const obsPedido = pasos.filter(s => s.action.tool === 'consolidar_pedido').map(s => corta(s.observation, 2000)).join(' ');
const r = respuesta.toLowerCase();
let etapa = 'info';
if (/\$\s?\d/.test(respuesta)) etapa = 'cotizacion';
if (usadas.includes('consultar_cobertura')) etapa = 'cobertura';
if (/(calle|n[uú]mero|nombre completo|colonia)/i.test(r) && /\?/.test(r)) etapa = 'captura';
if (usadas.includes('consolidar_pedido')) etapa = /NO REGISTRADO/.test(obsPedido) ? 'captura' : 'pedido';
if (escalo && etapa !== 'pedido') etapa = 'escalado';
if (falloIa) etapa = 'fallo_ia';
return [{ json: {
  leadId: n.leadId, sessionId: n.sessionId, entrada: n.entrada, corte: n.corte,
  respuesta, auto_escalar: String(auto && !mat), herramientas: usadas.join(','), materiales: mat,
  escalo, motivo, resumen: ti.resumen || (mat ? 'Pidió información por el anuncio de materiales. Preguntarle qué necesita y darle el precio.' : ''), detalle, fallo_ia: String(falloIa), etapa,
} }];

