// Saca el teléfono del cliente en 10 dígitos: campo Teléfono del contacto de Kommo; si no viene, cualquier campo del contacto con 10+ dígitos;
// si tampoco, el que manda ByteGPT. Así el bot no le pide al cliente un teléfono que ya tenemos.
let tel = '';
try {
  const c = $input.first().json || {};
  const campos = c.custom_fields_values || [];
  const f = campos.find(x => x.field_code === 'PHONE');
  if (f && f.values && f.values.length) tel = String(f.values[0].value || '');
  if (tel.replace(/\D/g, '').length < 10) for (const x of campos) for (const v of (x.values || [])) { const s = String(v.value || ''); if (/^\+?[\d\s()-]{10,}$/.test(s) && s.replace(/\D/g, '').length >= 10) { tel = s; break; } }
} catch (e) {}
if (tel.replace(/\D/g, '').length < 10) { try { tel = String($('Normalizar').first().json.telefono || ''); } catch (e) {} }
let d = tel.replace(/\D/g, '');
if (d.length > 10) d = d.slice(-10);
return [{ json: { telefono: d.length === 10 ? d : '' } }];

// Si la IA (OpenAI) falló, arma una alerta para Telegram (saldo agotado, límite de uso, etc.)
const a = $('Agente Super Tank').first().json || {};
const err = a.error ? String(a.error.message || a.error.description || JSON.stringify(a.error)) : '';
if (!err) return [];
const sinSaldo = /credit|quota|billing|insufficient/i.test(err);
const limite = /too many requests|rate limit|429/i.test(err);
const texto = sinSaldo
  ? '🚨 <b>OpenAI se quedó SIN SALDO</b>\nEl bot de WhatsApp no puede contestar. Recarga en platform.openai.com → Billing.'
  : limite ? '⚠️ <b>OpenAI está rechazando mensajes por límite de uso</b>\nEl bot de WhatsApp puede estar fallando. Si sigue, revisa el saldo en platform.openai.com → Billing.'
  : '⚠️ <b>La IA del bot de WhatsApp falló</b>\n' + err.slice(0, 300).replace(/&/g, '&amp;').replace(/</g, '&lt;');
return [{ json: { tipo: sinSaldo ? 'sin_saldo' : limite ? 'limite' : 'otro', texto } }];

