// Arma la tarea para Itzel: vence en 1 hora dentro del horario de oficina (L-S 8:00-15:00); fuera de horario, a las 9:00 del siguiente día hábil
const MINUTOS = 60;
const e = $('Revisar respuesta').first().json;
// material de construcción -> Jesús; todo lo demás -> Itzel (la tarea queda en Pendientes de Ventas web)
const sinAc = t => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const RESPONSABLE = /materiales de construccion/.test(sinAc(e.motivo)) ? 'jesus' : 'itzel';
const OFF = 6 * 3600000;
const mx = new Date(Date.now() - OFF);
const abre = 8, cierra = d => 15;
const h = mx.getUTCHours() + mx.getUTCMinutes() / 60;
let vence;
if (mx.getUTCDay() !== 0 && h >= abre && h + MINUTOS / 60 <= cierra(mx)) vence = new Date(Date.now() + MINUTOS * 60000);
else {
  const d = new Date(mx.getTime()); if (h >= abre) d.setUTCDate(d.getUTCDate() + 1);
  while (d.getUTCDay() === 0) d.setUTCDate(d.getUTCDate() + 1);
  d.setUTCHours(9, 0, 0, 0);
  vence = new Date(d.getTime() + OFF);
}
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const texto = `Bot WhatsApp · ${e.motivo}. ${e.resumen || ''} | Cliente: ${String(e.entrada || '').slice(0, 300)}`.slice(0, 900);
const horaVence = new Date(vence.getTime() - OFF).toISOString().slice(11, 16);
const convId = Number(e.leadId) >= 9000000000 ? Number(e.leadId) - 9000000000 : 0;
const liga = 'https://ai.adhesipro.com.mx/webhook/ventas' + (convId ? '?chat=' + convId : '');
const quien = RESPONSABLE === 'jesus' ? 'Jesús' : 'Itzel';
return [{ json: {
  aviso: `🙋 <b>El bot pasó un cliente a humano</b> · ${esc(e.motivo)}\n` + (e.resumen ? `${esc(e.resumen).slice(0, 400)}\n` : '') +
    `Cliente: <i>${esc(String(e.entrada || '').slice(0, 250))}</i>\n` +
    (/cancel/i.test(e.motivo || '') ? `🗑 <b>Cancélalo en Ventas web</b> (así se cancela en Microsip, hojas y planeador) y confírmale al cliente.\n` : /reprogram|fecha|urgente/i.test(e.motivo || '') ? `📅 Revísalo en el planeador. Si cambias el día, al cliente le llega solo el aviso de reprogramación.\n` : '') +
    `📋 Tarea para ${quien} · vence ${horaVence}\n👉 <a href="${liga}">Abrir el chat en DISACAM</a>` } }];

