      E'\n' ORDER BY familia, calidad, capacidad_l) FROM (SELECT p.*, (SELECT w.slug FROM vw_prod_modelo w WHERE translate(lower(w.familia), 'áéíóú', 'aeiou') = translate(lower(p.familia), 'áéíóú', 'aeiou') AND w.capacidad_l = p.capacidad_l AND w.calidad = p.calidad AND w.cat_visible ORDER BY w.orden LIMIT 1) AS slug FROM vw_bot_productos p WHERE p.activo) pp), '') AS catalogo,
