// Si en este turno se registró un pedido (consolidar_pedido con folio), se arma la consulta al planeador para darle al cliente su fecha estimada
const e = $input.first().json;
let ag = {}; try { ag = $('Agente Super Tank').first().json || {}; } catch (x) {}
const pasos = (ag.intermediateSteps || []).filter(s => s && s.action && s.action.tool === 'consolidar_pedido');
const paso = pasos[pasos.length - 1];
const ti = paso && typeof paso.action.toolInput === 'object' ? (paso.action.toolInput || {}) : {};
const obs = paso ? (typeof paso.observation === 'string' ? paso.observation : JSON.stringify(paso.observation || '')) : '';
const folio = (obs.match(/"folio"\s*:\s*"([A-Z]{1,4}\d{2,}|PRUEBA)"/) || [])[1] || '';
const mayoreo = /MAYOREO/.test(obs) || Number(ti.cantidad) > 3;
const actualizado = /ACTUALIZADO/.test(obs);
const pick = k => { const mm = obs.match(new RegExp('"' + k + '"\\s*:\\s*"([^"]*)"')); return mm ? mm[1] : ''; };
const fechaPedida = pick('fecha_pedida') || String(ti.fecha_pedida || '').trim();
const obligada = ['true', true].includes(ti.fecha_obligatoria);
const entregaActual = pick('entrega_actual');
// v4.12: solo se estima fecha para un pedido NUEVO. Si se actualizó (accesorio, pago, color), se conserva la fecha que ya tenía.
const estimar = !!paso && !!folio && !/NO REGISTRADO/.test(obs) && !mayoreo && !actualizado;
const cuerpo = { k: 'bc2dc5298e7d4ac3050a1251b8a434a1', simple: true,
  estimar: { cp: String(ti.cp || ''), colonia: String(ti.colonia || ''), direccion: String(ti.direccion || ''), producto: String(ti.producto || ''), litros: ti.capacidad_l || '', cantidad: ti.cantidad || 1 } };
return [{ json: { ...e, estimar, actualizado: actualizado && !!folio, fecha_pedida: fechaPedida, fecha_obligatoria: obligada, entrega_actual: entregaActual, folio_nuevo: folio, cuerpo_estimar: JSON.stringify(cuerpo) } }];

