// v4.12 · Renglón «Estatus» de la nota de pedido.
// - Pedido nuevo SIN día pedido: fecha estimada del planeador (como antes).
// - Pedido nuevo CON día pedido: se muestra el día que pidió el cliente y NO un rango distinto que lo contradiga.
// - Pedido ACTUALIZADO (accesorio, pago, color): se conserva la fecha que ya tenía; no se recalcula.
const e = $('Datos para estimar').first().json;
let est = null;
if (e.estimar) { try { let r = $('Estimar entrega (planeador)').first().json || {};
  if (typeof r.data === 'string') r = JSON.parse(r.data); if (typeof r === 'string') r = JSON.parse(r);
  est = r.estimado || null; } catch (x) {} }
let respuesta = String(e.respuesta || '');
const fp = String(e.fecha_pedida || '').trim();
const confirmar = 'y un día antes te pedimos confirmar que haya quien reciba.';
let linea = '';
if (e.estimar) {
  if (fp && e.fecha_obligatoria) linea = `Estatus: pedido registrado. Día que necesitas: ${fp}. Lo pedimos a rutas para ese día; si no se puede, te avisamos por aquí ANTES de programarlo para que decidas. Un día antes te pedimos confirmar que haya quien reciba.`;
  else if (fp) linea = `Estatus: pedido registrado. Día que pediste: ${fp}; lo tomamos en cuenta al programar tu ruta. Te confirmamos la fecha exacta por aquí ${confirmar}`;
  else if (est && est.rango) {
    // si antes en la conversación ya se le dio otro rango, se le dice claro que cambió (no dos fechas sueltas)
    let antes = ''; try { const u = [$('Mensajes del cliente').first().json.ultima_respuesta].concat($('Mensajes del cliente').first().json.ultimas || []); for (const t of u) { const mm = String(t || '').match(/entre el [a-záéíóú]+ \d{1,2} y el [a-záéíóú]+ \d{1,2}/i); if (mm) { antes = mm[0]; break; } } } catch (x) {}
    const nrm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
    if (antes && nrm(antes) !== nrm(est.rango)) linea = `Estatus: pedido registrado y considerado. Te había dicho ${antes}; al armar la ruta con tu pedido, la entrega quedaría ${est.rango}. Esta es la fecha que vale. Te confirmamos la fecha exacta por aquí ${confirmar}`;
    else linea = `Estatus: pedido registrado y considerado. Revisando nuestras rutas, se entregaría ${est.rango}. Te confirmamos la fecha exacta por aquí ${confirmar}`;
  }
  else linea = `Estatus: pedido registrado y considerado. En cuanto tenga fecha de entrega te la confirmamos por aquí, ${confirmar}`;
} else if (e.actualizado) {
  const actual = String(e.entrega_actual || '').trim();
  linea = 'Estatus: pedido actualizado con el mismo folio. ' + (actual ? `Tu entrega sigue considerada ${/^\d{2}\/\d{2}\/\d{4}$/.test(actual) ? 'para el ' + actual : actual}.` : 'La fecha de entrega no cambia; en cuanto la tengamos te la confirmamos por aquí.') + (fp ? ` Día que pediste: ${fp}.` : '');
}
if (linea) {
  const re = /^[*_ ]*Estatus\s*:.*$/mi;
  if (re.test(respuesta)) respuesta = respuesta.replace(re, linea);
  else if (/NOTA DE PEDIDO/i.test(respuesta)) { const g = respuesta.search(/Gracias por tu compra/i); respuesta = g >= 0 ? respuesta.slice(0, g) + linea + '\n' + respuesta.slice(g) : respuesta + '\n' + linea; }
}
// Ubicación para el chofer: se pide en la misma nota (si ya la mandó, no)
let yaUbic = false; try { yaUbic = !!$('Guardar ubicación').first().json.folio_ubicacion || !!$('Armar entrada').first().json.ubicacion; } catch (x) {}
if (e.estimar && !yaUbic && !/ubicaci[oó]n/i.test(respuesta)) respuesta = respuesta.trim() + '\nPara que el repartidor llegue más fácil, ¿nos compartes tu ubicación de WhatsApp? (en el clip, opción Ubicación)';
return [{ json: { ...e, respuesta, entrega_estimada: (est && est.rango) || '', estimado_motivo: (est && est.motivo) || '' } }];

// Las ligas cortas de Google Maps (maps.app.goo.gl) redirigen a una liga larga que trae las coordenadas.
// Si no se pueden sacar, se guarda la liga tal cual (el chofer la puede abrir igual).
const r = $input.first().json || {}, orig = String($('Armar entrada').first().json.ubicacion || '');
const h = r.headers || {}, loc = String(h.location || h.Location || '');
const co = s => { s = String(s || ''); try { s = decodeURIComponent(s); } catch (e) {}
  const m = s.match(/@(-?\d{1,2}\.\d{3,}),(-?\d{2,3}\.\d{3,})/) || s.match(/!3d(-?\d{1,2}\.\d{3,})!4d(-?\d{2,3}\.\d{3,})/) || s.match(/[?&](?:q|query|ll|destination)=(-?\d{1,2}\.\d{3,}),\s*\+?(-?\d{2,3}\.\d{3,})/) || s.match(/\/search\/(-?\d{1,2}\.\d{3,}),\s*\+?(-?\d{2,3}\.\d{3,})/);
  return m ? [m[1], m[2]] : null; };
const c = co(loc) || co(typeof r.body === 'string' ? r.body.slice(0, 30000) : '');
return [{ json: { url: c ? `https://www.google.com/maps/search/?api=1&query=${c[0]},${c[1]}` : orig, coord: c } }];

// Leads de MATERIALES (Lomas del Ajusco): el bot de tinacos no los atiende. Contesta una sola vez qué necesita y que un asesor le da el precio; después se calla.
// ===== EDITA AQUÍ =====
const EMBUDOS = ['lomas'];                  // es de materiales si el NOMBRE de su embudo en Kommo contiene alguna de estas palabras
const ANUNCIOS = ['120254368048550729'];    // o si viene de alguno de estos anuncios de Meta («Meta Ads ID del anuncio»)
// el bot de Kommo ya saluda («¿en qué le podemos ayudar?»), así que aquí NO se vuelve a preguntar si el cliente ya dijo qué quiere
const MENSAJE_PIDE = 'Gracias por escribir a Lomas del Ajusco 🏗️. Dinos qué material necesitas (producto y cantidad) y un asesor te contactará en un momento con el precio.';
const MENSAJE_RECIBIDO = '¡Gracias! Ya tomamos nota de lo que necesitas. Un asesor te contactará en un momento con el precio. 🙌';
// =======================
const J = b => { if (typeof b !== 'string') return b || {}; try { return JSON.parse(b || '{}'); } catch (x) { return {}; } };
let n = {}; try { n = $('Armar entrada').first().json || {}; } catch (e) {}
let lead = {}; try { lead = $('Kommo lead').first().json || {}; } catch (e) {}
let pips = []; try { pips = (J($('Embudos de Kommo').first().json.body)._embedded || {}).pipelines || []; } catch (e) {}
const pip = pips.find(p => Number(p.id) === Number(lead.pipeline_id));
const nombre = String((pip && pip.name) || '').toLowerCase();
let cc = []; try { cc = $('Kommo contacto').first().json.custom_fields_values || []; } catch (e) {}
const anuncios = [...(lead.custom_fields_values || []), ...cc].filter(c => /anuncio|ads id/i.test(String(c.field_name || ''))).map(c => String(((c.values || [])[0] || {}).value || '')).filter(Boolean);
let marcaDirecta = ''; try { marcaDirecta = String($('Normalizar').first().json.marca || ''); } catch (e) {}
// chats directos de WhatsApp (sin Kommo): el número de Construrama siempre es de materiales; el de Super Tank va al bot de tinacos
const materiales = !!n.leadId && (marcaDirecta === 'construrama' || (!!nombre && EMBUDOS.some(w => nombre.includes(w))) || anuncios.some(a => ANUNCIOS.includes(a)));
const previos = Number(($input.first().json || {}).previos || 0);
const txt = String(n.entrada || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const soloSaluda = txt.length < 45 && /^(hola|buen[oa]s?|buenas|info|informacion|quiero mas informacion|me gustaria|quisiera|necesito informacion|mas informacion|ayuda|disculpe|oiga)\b/.test(txt) && !/\d/.test(txt);
return [{ json: { materiales, silencio: materiales && previos > 0, output: materiales ? (soloSaluda ? MENSAJE_PIDE : MENSAJE_RECIBIDO) : '', embudo: nombre, anuncios: anuncios.join(',') } }];
